-- Paŝoj al plena posedo : réponses types (« corrigé type » montré aux correcteurs), lot 2 : leçons 5 à 8.
-- Questions sur le texte (5.3, 6.3, 7.3, 8.3), questions à retrouver (5.3), substantifs et adjectifs participes (5.4, 6.4),
-- propositions participiales à compléter (8.4, exemples seulement).
-- Rédigées d'après les textes et les réponses cochées « juste » par les correcteurs ; à relire par Emmanuelle.
-- Ne remplace pas une réponse type existante ; peut être rejoué sans risque.
SET NAMES utf8mb4;

UPDATE ekzerceroj SET respondo = 'Ĉefe en Ruslando.' WHERE id = 1138 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'En Francio, en Boulogne-sur-Mer (aŭgusto 1905).' WHERE id = 1139 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La unua momento estis iom embarasa kaj malrapida, la dua malpli, kaj la sekvantaj horoj alportis veran plezuron kaj pli kaj pli fluan elparolon. La kompreno ĉiam estis klara.' WHERE id = 1140 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĝi invitis kelkajn eksterlandajn esperantistojn al publikaj kunsidoj en somero 1903. La eksperimento bonege sukcesis, donis ideon al aliaj marbordaj grupoj francaj kaj anglaj, kaj el ĝi devenis la Universalaj Kongresoj.' WHERE id = 1141 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke la plej granda valoro de mondlingvo kuŝas en la parolado: Esperanto ne funkciu nur skribe, sed faciligu la vivon de vojaĝantoj kaj kongresanoj.' WHERE id = 1142 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'D-ro Zamenhof, la fondinto de Esperanto.' WHERE id = 1143 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar homoj el la tuta Eŭropo komprenis unu la alian kaj interparolis kvazaŭ bone konatoj; multaj parolis Esperanton la unuan fojon kaj miris pri ĝia facileco kaj flueco.' WHERE id = 1144 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'El la tuta Eŭropo, el landoj proksimaj kaj malproksimaj.' WHERE id = 1145 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La inspiron idean kaj sentimentan: oni vidis la fondinton kaj komprenis, ke forta “interna ideo” inspiras la tutan aferon.' WHERE id = 1146 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li estis malalta viro, timema, iom ĝenata, kun rondaj okulvitroj kaj saĝa bonkoreco de patra kuracisto.' WHERE id = 1147 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke Esperanto ne estas nura lingvo, sed rimedo al kunfratiĝo de homoj, simbolo de pli harmonia homaro.' WHERE id = 1148 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĝi donis al la lingvo animon kaj flugilojn: propran spiritan forton, kiel la “spirito” de la naciaj lingvoj, kaj signifon al ĝia ekliteraturo.' WHERE id = 1149 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĝi estis simpla kaj ripetema, kiel la komencaj literaturo kaj patriotismo de ĉiuj gentoj, kiuj estis eĉ pli simplaj.' WHERE id = 1150 AND ekzerco_id = 132 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiam okazis la unua kongreso de Esperanto?' WHERE id = 1151 AND ekzerco_id = 133 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'En kiu urbo okazis la unua kongreso de Esperanto?' WHERE id = 1152 AND ekzerco_id = 133 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiu promesis aranĝi la kongreson en sia urbo?' WHERE id = 1153 AND ekzerco_id = 133 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiuj konataj esperantaj verkistoj ĉeestis la kongreson?' WHERE id = 1154 AND ekzerco_id = 133 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'El kiu urbo venis Grabowski, Kabe kaj Leo Belmont?' WHERE id = 1155 AND ekzerco_id = 133 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉirkaŭ kio svarmis la fratiĝemaj homoj? (aŭ: Kie okazis la solena malfermo?)' WHERE id = 1156 AND ekzerco_id = 133 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kian sukceson alportis la kongreso?' WHERE id = 1157 AND ekzerco_id = 133 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'De kie venis la kongresanoj?' WHERE id = 1158 AND ekzerco_id = 133 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiu opiniis, ke “Esperanto estas nura lingvo kaj nenio pli”?' WHERE id = 1159 AND ekzerco_id = 133 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kio estis mondlingvo por la fondinto?' WHERE id = 1160 AND ekzerco_id = 133 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Policanoj kaptis la ŝtelantojn.' WHERE id = 1174 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Policanoj kaptis la ŝtelintojn.' WHERE id = 1175 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Policanoj kaptis la ŝtelontojn.' WHERE id = 1176 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Oni pendigis la murdinton.' WHERE id = 1177 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La solenontoj rapidis al la preĝejo.' WHERE id = 1178 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Multaj ĉeestantoj kuraĝigis la luktantojn.' WHERE id = 1179 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Multaj ĉeestantoj aplaŭdis la luktintojn.' WHERE id = 1180 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ĉeestontoj diskutis la luktontojn.' WHERE id = 1181 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ĉeestintoj diskutis la luktintojn.' WHERE id = 1182 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ĉeestontoj aplaŭdos la parolinton (aŭ: la paroladinton).' WHERE id = 1183 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Advokato Michaux pridemandis la akuziton.' WHERE id = 1184 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La pendigoto preĝis.' WHERE id = 1185 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La atakato vigle sin defendis.' WHERE id = 1186 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ĉasantoj kaptos tamen la avertiton.' WHERE id = 1187 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La alparolitinoj rigardis kun surprizo la senditon.' WHERE id = 1188 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La liberigitoj ne estas fuĝintoj.' WHERE id = 1189 AND ekzerco_id = 136 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ŝi aŭskultis en la radio prelegon “Al gepatroj pri la edukado”.' WHERE id = 1192 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar li revenis hejmen nur je la deka vespere kaj ankoraŭ ne vespermanĝis.' WHERE id = 1193 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke li estas senpacienca: de li la infano lernas la senpaciencon.' WHERE id = 1194 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar dum ŝi parolis, ŝi eksaltis kaj promenis tien kaj reen.' WHERE id = 1195 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ne: lia edzino unue interpretis al li la tutan radiparoladon dum mallonga horeto, kaj nur poste li ricevis la vespermanĝon.' WHERE id = 1196 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li ricevis fritaĵon. Li manĝis ĝin per forko (sen tranĉilo) kaj avide.' WHERE id = 1197 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li metis ĝin sur la apogilon de seĝo.' WHERE id = 1198 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li metis ĝin laŭ ordo, kaj ankaŭ la vestaĵojn de sia fileto.' WHERE id = 1199 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Post la noktomezo. La edzino vekis lin je la sepa horo matene.' WHERE id = 1200 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar lia edzino volis, ke la infano lernu diligentecon: la filo ne vidu sian patron kuŝi, kiam li mem jam devas iri al la lernejo.' WHERE id = 1201 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ne: li ofte devis enkuri al sia edzino, ĉar li ne trovis la sukeron, la kafon, la buteron.' WHERE id = 1202 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Sian fileton kaj onklon Keceli, la domzorganton.' WHERE id = 1203 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Sube en la ĝardeno.' WHERE id = 1204 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke li estas la teroristo de la tuta domo.' WHERE id = 1205 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar ŝi ne havas tempon: ŝi ĉiam edukas paĉjon (la patron).' WHERE id = 1206 AND ekzerco_id = 139 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Edukitaj infanoj estas diligentaj kaj disciplinaj.' WHERE id = 1207 AND ekzerco_id = 140 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Sur la tablo kuŝis fritota fiŝo.' WHERE id = 1208 AND ekzerco_id = 140 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La venonta tago estos tre plena de okupoj.' WHERE id = 1209 AND ekzerco_id = 140 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Tiu kesto estas plenigota.' WHERE id = 1210 AND ekzerco_id = 140 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La proksimiĝantaj barbaroj starigos teroron, se ili ne estos venkitaj.' WHERE id = 1211 AND ekzerco_id = 140 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La riproĉataj knaboj estis malobeintaj la regularon.' WHERE id = 1212 AND ekzerco_id = 140 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La tiam fluanta rivero alportis la falintan arbon.' WHERE id = 1213 AND ekzerco_id = 140 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La organizitaj esperantistoj protestis al la ministro fuŝparolinta pri la lingvo.' WHERE id = 1214 AND ekzerco_id = 140 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La kreita embaraso tute regis la ĉeestantajn personojn.' WHERE id = 1215 AND ekzerco_id = 140 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La delegitajn kaj jam kunvenintajn personojn bonvenigos la urbestraro.' WHERE id = 1216 AND ekzerco_id = 140 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Oficisto, kiu konsideras sin intelektulo, parolas al advokato (en drinkejo, trinkante brandon).' WHERE id = 1238 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Laŭ li, ili estis sinceraj kamaradoj, eĉ ide-kamaradoj: li ŝatis la junulon kiel filon aŭ fraton.' WHERE id = 1239 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Pro mensoga akuzo: liaj malamikoj trovis du falsajn atestantojn. Li ankaŭ tro babilis kaj malamikigis al si ĉiujn gravulojn de la lando.' WHERE id = 1240 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li pretendas havi ilin (“ankaŭ ni ja havas niajn ideojn”), sed fakte ne: li neniam malfermas la buŝon kaj konsilas vivi kviete en angulo.' WHERE id = 1241 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Laŭ li, jes: li vagadis ĝis vespero de loko al loko kiel frenezulo kaj eĉ ploris.' WHERE id = 1242 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Jes: oni diras, ke li faris laŭdindan defendparoladon dum la unua akto, kaj eble li savos la junulon.' WHERE id = 1243 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke la malliberejo estos bona leciono por la junulo: li bezonas tian punon por iĝi matura kaj kompreni la vivon (kiel diris Mussolini).' WHERE id = 1244 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Unue li laŭdas la amikecon kaj la junulon kaj diras, ke li ploris pro li. Poste li diras, ke la junulo ne estis tute senkulpa, kaj ke la malliberejo estos bona leciono por li. Tiam li petas la advokaton ne defendi lin, kaj proponas al li tridek lirojn, por ke li kondamnigu lin. Fine li konfesas, ke li anstataŭas la junulon en lia posteno kaj ricevas krom-salajron.' WHERE id = 1245 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: “mi ploris”, “mia koro preskaŭ krevis”; “mi ne havas monon” (sed li proponas tridek lirojn); “mi estas preta oferi mian animon por kamarado”; “mi ne kredas, ke profitemo regas la mondon”.' WHERE id = 1246 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Hipokrita, egoisma kaj profitema homo, malkuraĝa oportunisto.' WHERE id = 1247 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Verŝajne ne: la advokato skuas la kapon kaj demandas, de kie li prenos la monon; tiel la parolanto malkaŝas sian veran motivon.' WHERE id = 1248 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona opinio. Ekzemple: li kuraĝe agis laŭ siaj konvinkoj, sed neprudente: li tro babilis kaj malamikigis al si ĉiujn gravulojn.' WHERE id = 1249 AND ekzerco_id = 144 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Maljuna fraŭlo, kiu amikiĝas tre malfacile kaj havas nur du-tri amikojn; li suferis en la urbeto kaj iom bedaŭras, ke li ne edziĝis.' WHERE id = 1271 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Rapide kaj sen ia ajn signifa okazo: ili renkontiĝis, paroladis kaj bonege komprenis unu la alian, ĉar ambaŭ malŝatis la sociajn formalaĵojn.' WHERE id = 1272 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li amis belan knabinon el nobla, riĉa familio, sed li estis malriĉa; ŝiaj gepatroj malvolis, kaj ili devis adiaŭi.' WHERE id = 1273 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar li gvidis la konstruon de la kanalo, kaj oni konfidis al li ankaŭ ĝian prizorgadon kaj inspekton.' WHERE id = 1274 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ŝi estis preskaŭ dek jarojn pli juna ol li (do ĉirkaŭ 25-30-jara).' WHERE id = 1275 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar oni amas aŭ ne amas: la amo ne havas gradojn.' WHERE id = 1276 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke ŝi elektis lin kaj ne iun alian, pli belan aŭ pli saĝan, kvankam duono de la klaso estis enamiĝinta al ŝi.' WHERE id = 1277 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li forlasis la urbon por gajni sian panon: li serĉis laboron kaj vagadis en Francujo.' WHERE id = 1278 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĝi ne malpliiĝis: li amis ŝin same kiel antaŭe, sed li kutimiĝis al tiu amo; ĝi iĝis parto de lia vivo, kontinua sento jam ne sentata.' WHERE id = 1279 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona opinio. Ekzemple: tio estas stranga kaj montras, ke li ne multe pripensis la estontecon: li konis nur ŝian universitatan adreson kaj la nomon de ŝia urbeto.' WHERE id = 1280 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar la konkurso ankoraŭ ne estis fermita (ankoraŭ ses monatoj) kaj la versaĵoj aperis anonime.' WHERE id = 1281 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li tremis kaj demandis sin, ĉu ĉio ne estas superflua: lia vivo jam preskaŭ enordiĝis, verŝajne ankaŭ ŝia, kaj nun ĉio povus renversiĝi.' WHERE id = 1282 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke ŝi sendis la poemon, ke ŝi ne forgesis lin, ke ŝi ankoraŭ amas kaj atendas lin, kaj ŝi demandis, ĉu li volas iri al ŝi.' WHERE id = 1283 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke ŝi estas lia edzino: li supozis “happy end”.' WHERE id = 1284 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La inĝeniero unuafoje alrigardis lin, poste silentis dum longaj minutoj, rigardante la fajron; tiam la aŭtoro sentis, ke okazos io neatendita.' WHERE id = 1285 AND ekzerco_id = 148 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Ŝercante, li ridigis ĉiujn.' WHERE id = 1286 AND ekzerco_id = 149 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Renversinte sian kontraŭulon, la luktisto gajnis la batalon.' WHERE id = 1287 AND ekzerco_id = 149 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Ekfumonte cigaredon, li serĉis alumeton en sia poŝo.' WHERE id = 1288 AND ekzerco_id = 149 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Komunikite per ĉiuj ĵurnaloj, la novaĵo rapide konatiĝis tra la tuta lando.' WHERE id = 1289 AND ekzerco_id = 149 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Sorĉate de la bela ĉirkaŭaĵo, ŝi decidis resti tie kelkajn tagojn.' WHERE id = 1290 AND ekzerco_id = 149 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Alparolote de la reĝo, la soldato ekstaris rekte.' WHERE id = 1291 AND ekzerco_id = 149 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Kuironte la vespermanĝon, ŝi unue lavis la legomojn.' WHERE id = 1292 AND ekzerco_id = 149 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Kritikinte la mankojn de ĉiuj aliaj, li ne vidis la siajn.' WHERE id = 1293 AND ekzerco_id = 149 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Tiel fanfaroninte pri siaj kapabloj, li devis nun pruvi ilin.' WHERE id = 1294 AND ekzerco_id = 149 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Turnite de la forta vento, la boato renversiĝis.' WHERE id = 1295 AND ekzerco_id = 149 AND COALESCE(respondo, '') = '';

-- Vérification
SELECT ekzerco_id, COUNT(*) AS demandoj, SUM(COALESCE(respondo, '') <> '') AS kun_respondo FROM ekzerceroj
  WHERE ekzerco_id IN (132, 133, 136, 139, 140, 144, 148, 149) AND forigita = 0 GROUP BY ekzerco_id;
